head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST60212";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst60212.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return " <![CDATA[http://" + String((dma_pageContext.get("rssIp") ?? "")) + ":" + String((dma_pageContext.get("rssPort") ?? "")) + "/disclosure/todaydisclosure.do?method=searchTodayDisclosureMain]]\u003e"; } },
        { childId: "__rb1", fn: function () { return " <![CDATA[http://" + String((dma_pageContext.get("rssIp") ?? "")) + ":" + String((dma_pageContext.get("rssPort") ?? "")) + "/common/disclsviewer.do?method=searchInitInfo&acptNo=&docno=]]\u003e"; } },
        { childId: "__rb2", fn: function () { return " <![CDATA[http://" + String((dma_pageContext.get("rssIp") ?? "")) + ":" + String((dma_pageContext.get("rssPort") ?? "")) + "/common/disclsviewer.do?method=searchInitInfo&acptNo=&docno=]]\u003e"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };
